-- Run once on a NEW Supabase project.
create extension if not exists pgcrypto;
create table public.positions(id uuid primary key default gen_random_uuid(),name text unique not null,description text,is_active boolean default true,sort_order int default 0,created_at timestamptz default now());
insert into public.positions(name,sort_order) values ('ครู',1),('บุคลากร',2),('หัวหน้าฝ่ายงาน',3),('รองผู้อำนวยการสถานศึกษา',4),('ผู้อำนวยการสถานศึกษา',5);
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',system_role text not null default 'user' check(system_role in('user','admin','super_admin')),position_id uuid references positions(id) on delete set null,department text,is_active boolean default true,can_review boolean default false,can_approve boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.documents(id uuid primary key default gen_random_uuid(),title text not null,description text,file_path text unique not null,file_name text not null,file_size bigint not null,owner_id uuid references profiles(id),status text not null default 'draft' check(status in('draft','submitted','in_review','changes_requested','approved','archived','cancelled')),revision int default 1,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.workflow_templates(id uuid primary key default gen_random_uuid(),name text not null,description text,is_active boolean default true,created_by uuid references profiles(id),created_at timestamptz default now());
create table public.workflow_template_steps(id uuid primary key default gen_random_uuid(),template_id uuid references workflow_templates(id) on delete cascade,step_order int not null,name text not null,assignee_type text default 'position',position_id uuid references positions(id),approval_mode text default 'any',requires_signature boolean default false);
create table public.document_workflows(id uuid primary key default gen_random_uuid(),document_id uuid unique references documents(id) on delete cascade,template_id uuid references workflow_templates(id),current_step int default 1,status text default 'active',created_at timestamptz default now());
create table public.document_workflow_steps(id uuid primary key default gen_random_uuid(),workflow_id uuid references document_workflows(id) on delete cascade,step_order int not null,name text not null,approval_mode text default 'any',requires_signature boolean default false,status text default 'waiting' check(status in('waiting','active','approved','rejected','skipped')),decided_at timestamptz);
create table public.workflow_step_assignees(id uuid primary key default gen_random_uuid(),step_id uuid references document_workflow_steps(id) on delete cascade,user_id uuid references profiles(id),status text default 'pending',acted_at timestamptz,unique(step_id,user_id));
create table public.workflow_actions(id uuid primary key default gen_random_uuid(),document_id uuid references documents(id),step_id uuid references document_workflow_steps(id),actor_id uuid references profiles(id),action text not null,comment text,created_at timestamptz default now());
create table public.signatures(id uuid primary key default gen_random_uuid(),document_id uuid references documents(id) on delete cascade,user_id uuid references profiles(id),page_number int not null,x_ratio numeric not null,y_ratio numeric not null,width_ratio numeric not null,height_ratio numeric not null,image_path text,signed_at timestamptz default now());
create table public.document_archives(id uuid primary key default gen_random_uuid(),document_id uuid references documents(id),drive_id text,item_id text,web_url text,file_name text,file_size bigint,sha256 text,archived_by uuid references profiles(id),archived_at timestamptz default now());
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references profiles(id),action text not null,entity_type text,entity_id uuid,details jsonb,created_at timestamptz default now());
create or replace function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1)));return new;end$$;
create trigger auth_profile after insert on auth.users for each row execute procedure public.new_profile();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and system_role in('admin','super_admin') and is_active)$$;
create or replace function public.instantiate_workflow(p_document_id uuid,p_template_id uuid) returns uuid language plpgsql security definer set search_path=public as $$declare w uuid;s record;st uuid;begin if not exists(select 1 from documents where id=p_document_id and owner_id=auth.uid()) then raise exception 'ไม่มีสิทธิ์';end if;insert into document_workflows(document_id,template_id) values(p_document_id,p_template_id) returning id into w;for s in select * from workflow_template_steps where template_id=p_template_id order by step_order loop insert into document_workflow_steps(workflow_id,step_order,name,approval_mode,requires_signature,status) values(w,s.step_order,s.name,s.approval_mode,s.requires_signature,case when s.step_order=1 then 'active' else 'waiting' end) returning id into st;insert into workflow_step_assignees(step_id,user_id) select st,id from profiles where position_id=s.position_id and is_active and (can_review or can_approve);end loop;update documents set status='in_review' where id=p_document_id;return w;end$$;
create or replace function public.act_on_workflow(p_document_id uuid,p_action text,p_comment text default '') returns void language plpgsql security definer set search_path=public as $$declare st document_workflow_steps%rowtype;wf document_workflows%rowtype;begin select s.* into st from document_workflow_steps s join document_workflows w on w.id=s.workflow_id join workflow_step_assignees a on a.step_id=s.id where w.document_id=p_document_id and s.status='active' and a.user_id=auth.uid() limit 1;if st.id is null then raise exception 'ไม่ได้รับมอบหมายในขั้นตอนปัจจุบัน';end if;select * into wf from document_workflows where id=st.workflow_id;if p_action='rejected' then update document_workflow_steps set status='rejected',decided_at=now() where id=st.id;update documents set status='changes_requested' where id=p_document_id;else update workflow_step_assignees set status='approved',acted_at=now() where step_id=st.id and user_id=auth.uid();update document_workflow_steps set status='approved',decided_at=now() where id=st.id;update document_workflow_steps set status='active' where workflow_id=wf.id and step_order=st.step_order+1;if not found then update documents set status='approved' where id=p_document_id;update document_workflows set status='completed' where id=wf.id;else update document_workflows set current_step=st.step_order+1 where id=wf.id;end if;end if;insert into workflow_actions(document_id,step_id,actor_id,action,comment) values(p_document_id,st.id,auth.uid(),p_action,p_comment);end$$;
alter table positions enable row level security;alter table profiles enable row level security;alter table documents enable row level security;alter table workflow_templates enable row level security;alter table workflow_template_steps enable row level security;alter table document_workflows enable row level security;alter table document_workflow_steps enable row level security;alter table workflow_step_assignees enable row level security;alter table workflow_actions enable row level security;alter table signatures enable row level security;alter table document_archives enable row level security;alter table audit_logs enable row level security;
create policy positions_read on positions for select to authenticated using(true);create policy positions_admin on positions for all to authenticated using(is_admin()) with check(is_admin());
create policy profiles_read on profiles for select to authenticated using(true);
create policy docs_read on documents for select to authenticated using(owner_id=auth.uid() or is_admin() or exists(select 1 from document_workflows w join document_workflow_steps s on s.workflow_id=w.id join workflow_step_assignees a on a.step_id=s.id where w.document_id=documents.id and a.user_id=auth.uid()));create policy docs_insert on documents for insert to authenticated with check(owner_id=auth.uid());create policy docs_update on documents for update to authenticated using(owner_id=auth.uid() or is_admin());
create policy templates_read on workflow_templates for select to authenticated using(true);create policy templates_admin on workflow_templates for all to authenticated using(is_admin()) with check(is_admin());create policy template_steps_read on workflow_template_steps for select to authenticated using(true);create policy template_steps_admin on workflow_template_steps for all to authenticated using(is_admin()) with check(is_admin());
create policy wf_read on document_workflows for select to authenticated using(true);create policy wf_insert on document_workflows for insert to authenticated with check(true);create policy steps_read on document_workflow_steps for select to authenticated using(true);create policy assignees_read on workflow_step_assignees for select to authenticated using(true);create policy actions_read on workflow_actions for select to authenticated using(true);create policy sig_rw on signatures for all to authenticated using(user_id=auth.uid() or is_admin()) with check(user_id=auth.uid());create policy archives_read on document_archives for select to authenticated using(true);create policy audit_admin on audit_logs for select to authenticated using(is_admin());
grant execute on function instantiate_workflow(uuid,uuid) to authenticated;grant execute on function act_on_workflow(uuid,text,text) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('documents','documents',false,52428800,array['application/pdf']),('signatures','signatures',false,3145728,array['image/png']) on conflict(id) do nothing;
create policy document_upload on storage.objects for insert to authenticated with check(bucket_id='documents' and (storage.foldername(name))[1]=auth.uid()::text);create policy document_read on storage.objects for select to authenticated using(bucket_id='documents' and exists(select 1 from documents d where d.file_path=name and (d.owner_id=auth.uid() or is_admin() or exists(select 1 from document_workflows w join document_workflow_steps s on s.workflow_id=w.id join workflow_step_assignees a on a.step_id=s.id where w.document_id=d.id and a.user_id=auth.uid()))));
